#include <chrono>
#include <cmath>
#include <complex>
#include <cstdlib>
#include <iomanip>
#include <iostream>
#include <string>
#include <utility>
#include <vector>

struct Prepared {
    std::vector<float> window;
    // One forward-transform twiddle per stage offset.  A stage of width m
    // uses the first m/2 entries.
    std::vector<std::vector<std::complex<float>>> twiddles;
    explicit Prepared(int n) : window(n), twiddles() {
        const double tau=6.283185307179586476925286766559;
        for(int i=0;i<n;i++)
            window[i]=0.5-0.5*std::cos(tau*i/(n-1));
        for(int width=2;width<=n;width*=2) {
            std::vector<std::complex<float>> stage(width/2);
            for(int j=0;j<width/2;j++) {
                const double a=-tau*j/width;
                stage[j]={static_cast<float>(std::cos(a)),static_cast<float>(std::sin(a))};
            }
            twiddles.push_back(std::move(stage));
        }
    }
};

static void fft(std::vector<std::complex<float>>& a,const Prepared& prep) {
    const int n=static_cast<int>(a.size());
    for(int i=1,j=0;i<n;i++) {
        int bit=n>>1;
        for(;j&bit;bit>>=1)j^=bit;
        j^=bit;
        if(i<j)std::swap(a[i],a[j]);
    }
    int stage=0;
    for(int width=2;width<=n;width*=2,stage++) {
        const int half=width/2;
        const auto& roots=prep.twiddles[stage];
        for(int base=0;base<n;base+=width)
            for(int j=0;j<half;j++) {
                const auto even=a[base+j];
                const auto odd=a[base+j+half]*roots[j];
                a[base+j]=even+odd;
                a[base+j+half]=even-odd;
            }
    }
}

static double sample(int channel,int window,int i,int n){
    const double tau=6.283185307179586476925286766559;
    return 0.55*std::sin(tau*i*(3+channel%11)/n+0.07*window)
         + 0.22*std::cos(tau*i*(17+window%7)/n+0.03*channel)
         + 0.001*(int((i*17+channel*31+window*13)%101)-50);
}
static int direct(int channels,int windows,int n){
    const int bins=n/2+1;
    std::vector<double> all(std::size_t(channels)*windows*bins);
    using clock=std::chrono::steady_clock;const auto begin=clock::now();
    for(int c=0;c<channels;c++)for(int w=0;w<windows;w++){
        std::vector<double> frame(n);
        for(int i=0;i<n;i++)frame[i]=sample(c,w,i,n)*(0.5-0.5*std::cos(6.283185307179586476925286766559*i/(n-1)));
        for(int k=0;k<bins;k++){
            double re=0,im=0;
            for(int i=0;i<n;i++){
                const double a=-6.283185307179586476925286766559*k*i/n;
                re+=frame[i]*std::cos(a); im+=frame[i]*std::sin(a);
            }
            all[(std::size_t(c)*windows+w)*bins+k]=re*re+im*im;
        }
    }
    const double sec=std::chrono::duration<double>(clock::now()-begin).count();
    std::cout<<std::setprecision(17)<<"seconds="<<sec<<" algorithm=direct channels="<<channels
             <<" windows="<<windows<<" samples="<<n<<" outputs="<<all.size()<<" values=";
    for(double v:all)std::cout<<v<<',';
    std::cout<<'\n';return 0;
}
static int run(int channels,int windows,int n,std::string mode){
    if(channels<1||channels>64||windows<1||windows>8||n<16||n>1024||(n&(n-1)))return 2;
    if(mode!="auto"&&mode!="direct"){std::cerr<<"mode must be auto or direct\n";return 2;}
    if(mode=="direct")return direct(channels,windows,n);
    static std::vector<std::pair<int,Prepared>> cache;
    Prepared* prep=nullptr;
    for(auto& entry:cache)if(entry.first==n){prep=&entry.second;break;}
    if(!prep){cache.emplace_back(n,Prepared(n));prep=&cache.back().second;}
    const int bins=n/2+1;
    std::vector<double> all(std::size_t(channels)*windows*bins);
    using clock=std::chrono::steady_clock;const auto begin=clock::now();
    for(int c=0;c<channels;c++)for(int w=0;w<windows;w++){
        std::vector<std::complex<float>> frame(n);
