    std::cout<<std::setprecision(17)<<"seconds="<<sec<<" algorithm=fft channels="<<channels
             <<" windows="<<windows<<" samples="<<n<<" outputs="<<all.size()<<" values=";
    for(double v:all)std::cout<<v<<',';
    std::cout<<'\n';return 0;
}
